// Column radiator (IRSAP Tesi) or towel warmer (IRSAP Kart) instead of a plain box
function radiatorDetail(poly, z0, z1, mk) {
  const xs = poly.map(p => p[0]), ys = poly.map(p => p[1]);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  const alongX = (x1 - x0) >= (y1 - y0), len = alongX ? x1 - x0 : y1 - y0, a0 = alongX ? x0 : y0;
  const R2 = (s, e, d0, d1) => alongX ? R(s, e, y0 + d0, y0 + d1) : R(x0 + d0, x0 + d1, s, e);
  const dep = alongX ? y1 - y0 : x1 - x0, mat = mk === 'towel' ? M.towel : M.radiator;
  if (mk === 'radiator') {
    const n = Math.max(2, Math.round(len / 4.5)), pitch = len / n;
    for (let i = 0; i < n; i++) prism(R2(a0 + i * pitch + .5, a0 + (i + 1) * pitch - .5, 0, dep), z0, z1, mat, G.fittings, { edges:false });
    prism(R2(a0, a0 + len, dep * .35, dep * .65), z0 + 2, z0 + 5, mat, G.fittings, { edges:false });     // headers
    prism(R2(a0, a0 + len, dep * .35, dep * .65), z1 - 5, z1 - 2, mat, G.fittings, { edges:false });
  } else {
    prism(R2(a0, a0 + 3, 0, dep), z0, z1, mat, G.fittings, { edges:false });                            // collectors
    prism(R2(a0 + len - 3, a0 + len, 0, dep), z0, z1, mat, G.fittings, { edges:false });
    for (let z = z0 + 4; z < z1 - 2; z += 5.5) prism(R2(a0 + 3, a0 + len - 3, dep * .3, dep * .7), z, z + 2, mat, G.fittings, { edges:false });
  }
}
// Painted skirting (8 cm) along every wall face of the parquet rooms; door openings and window niches stay clear
const skirtRay = new THREE.Raycaster();
function buildSkirting() {
  G.walls.updateMatrixWorld(true);
  const dir = new THREE.Vector3(), org = new THREE.Vector3();
  for (const r of PLAN.rooms) {
    if (r.floor !== 'parquet') continue;
    const P = r.poly, L = lvl(...(r.label ?? cen(P)));
    if (L + 3 > CUT) continue;
    for (let i = 0; i < P.length; i++) {
      const [ax, ay] = P[i], [bx, by] = P[(i + 1) % P.length], len = Math.hypot(bx - ax, by - ay);
      const ux = (bx - ax) / len, uy = (by - ay) / len;
      let nx = -uy, ny = ux; if (!inPoly([(ax + bx) / 2 - nx * 3, (ay + by) / 2 - ny * 3], P)) { nx = -nx; ny = -ny; }   // n = outward
      let run = null; const runs = [];
      for (let s = 2; s <= len - 2; s += 4) {
        const px = ax + ux * s - nx * 2, py = ay + uy * s - ny * 2;
        org.set(wx(px), (L + 5) * S, wz(py)); dir.set(nx, 0, ny);
        skirtRay.set(org, dir); skirtRay.far = .06;
        const hit = skirtRay.intersectObjects(G.walls.children, false).some(h => h.object.isMesh && h.object.material !== M.glass);
        if (hit) { if (!run) run = [s - 2, s + 2]; else run[1] = s + 2; } else if (run) { runs.push(run); run = null; }
      }
      if (run) runs.push(run);
      for (const [s0, s1] of runs) {
        if (s1 - s0 < 6) continue;
        const e0 = Math.max(0, s0 - 1), e1 = Math.min(len, s1 + 1);
        const q = [[ax + ux * e0, ay + uy * e0], [ax + ux * e1, ay + uy * e1]];
        const poly = [q[0], q[1], [q[1][0] - nx * 1.2, q[1][1] - ny * 1.2], [q[0][0] - nx * 1.2, q[0][1] - ny * 1.2]];
        prism(poly, L, L + 8, M.boiserie, G.fittings, { edges:false });
      }
    }
  }
}
