// Dining chair at plan point (cx, cy); dir = direction the sitter faces ([±1,0] or [0,±1])
function diningChair(cx, cy, [dx, dy]) {
  const h = 22;
  for (const [ax, ay] of [[-1,-1],[1,-1],[-1,1],[1,1]]) soft(cx + ax * 19 - 1.5, cx + ax * 19 + 1.5, cy + ay * 19 - 1.5, cy + ay * 19 + 1.5, 0, 44, FM.oak, .5);
  soft(cx - h, cx + h, cy - h, cy + h, 44, 49, FM.seat, 2);
  const bx = cx - dx * 20, by = cy - dy * 20;           // backrest on the side away from the table
  if (dx) soft(bx - 2, bx + 2, cy - 20, cy + 20, 49, 84, FM.oak, 1.5); else soft(cx - 20, cx + 20, by - 2, by + 2, 49, 84, FM.oak, 1.5);
}
// Swivel task chair facing -y (toward a desk on the north wall)
function taskChair(cx, cy) {
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2, leg = new THREE.Mesh(new THREE.BoxGeometry(.3, .03, .04), FM.metal);
    leg.position.set(wx(cx) + Math.cos(a) * .15, .05, wz(cy) + Math.sin(a) * .15); leg.rotation.y = -a; G.furniture.add(leg);
  }
  const post = new THREE.Mesh(new THREE.CylinderGeometry(.025, .03, .36, 16), FM.metal); post.position.set(wx(cx), .25, wz(cy)); G.furniture.add(post);
  soft(cx - 25, cx + 25, cy - 24, cy + 24, 43, 51, FM.mesh, 4);                    // seat
  soft(cx - 23, cx + 23, cy + 22, cy + 27, 56, 108, FM.mesh, 4);                   // tall backrest
  soft(cx - 2, cx + 2, cy + 24, cy + 28, 46, 58, FM.metal, 1);                      // back spine
  for (const s of [-1, 1]) { soft(cx + s * 27 - 2, cx + s * 27 + 2, cy - 12, cy + 14, 64, 67, FM.mesh, 1.5); soft(cx + s * 27 - 1, cx + s * 27 + 1, cy + 8, cy + 11, 50, 64, FM.metal, .5); }
}

